const INFO: Record<string, Obj> = {
    '/about': { tag: 'THE PEOPLE BEHIND THE POSSIBILITIES', title: 'Built around creative people.', desc: 'AI opens new creative possibilities. The right collaboration turns those possibilities into work that matters.', sections: [['Our purpose', 'CreaXa connects brands and agencies with creators who work with generative tools. We put capability, process and creative context alongside the final image or film.'], ['Clarity makes better work', 'Every campaign starts with a documented brief. Every collaboration keeps its scope, files, revisions and delivery connected.'], ['Trust is specific', 'Creative capabilities start as self-declared claims. Evidence and review are clearly distinguished. No automatic verification badge replaces the context behind the work.']] },
    '/for-brands': { tag: 'FOR BRANDS & AGENCIES', title: 'Your ambition. Their perspective.', desc: 'Find AI creative partners through capabilities, original work and a brief that means business.', sections: [['Start with a clear vision', 'Define content type, creative style, platform, aspect ratio, language and deliverables. Set a real budget, deadline, revision allowance and intended usage.'], ['Find capability that fits', 'Search creator tools, specialization, industries and supported formats. Campaign matching explains the underlying factors and respects required capabilities.'], ['Keep the whole process together', 'Send an invitation with clear terms. When accepted, a shared workspace tracks messages, versioned files, revision requests, approval and delivery.']] },
    '/for-creators': { tag: 'FOR ORIGINAL MINDS', title: 'Make your process part of your story.', desc: 'A place for the vision, tools and creative thinking behind your work.', sections: [['Publish your perspective', 'Build a profile with your specializations, toolkit, output formats, industries, rates and availability. Keep your capabilities accurate and current.'], ['Show more than the result', 'Add original image and video projects with tools, workflow, contribution and commercial-use declarations. Private evidence stays separate from public media.'], ['Choose your collaborations', 'Review campaign invitations, agree the scope and work alongside your client through submission, revision, approval and final delivery.']] },
    '/how-it-works': { tag: 'FROM FIRST SPARK TO FINAL FRAME', title: 'An idea. A connection. A creation.', desc: 'A considered process for brands, agencies and AI creators.', sections: [['01 / Define the brief', 'Brands and agencies set the campaign objective, creative requirements, budget, timeline, deliverables and commercial-use expectations.'], ['02 / Discover your partner', 'Browse published profiles and original work. Refine by style, tools, format, industry and availability, or view explained campaign compatibility.'], ['03 / Agree the scope', 'Invite a creator with a proposed budget, start date, revision allowance and rights terms. Review and acceptance create the shared project agreement.'], ['04 / Create and refine', 'Keep messages and reference files in one workspace. Creators submit versioned deliverables; brands approve or request changes within the agreed allowance.'], ['05 / Deliver with clarity', 'After approval, the creator delivers the final version and the brand completes the workspace. Delivery and payment settlement remain separate.']] },
    '/privacy': { tag: 'YOUR DATA, WITH CONTEXT', title: 'Privacy policy.', desc: 'Last updated 12 October 2026.', sections: [['Account information', 'CreaXa receives a Site-specific identity ID, email and optional display name through ChatGPT sign-in. Marketplace account details, role, profile and organization information are stored in the Site database. Your password is not received or stored by CreaXa.'], ['Public and private content', 'Published creator profiles and portfolio media are visible to people permitted to access this Site. Campaigns, invitations, project files and conversations are accessible to their authorized owners and participants. Verification evidence is private to its owner and authorized moderators.'], ['Storage and providers', 'Structured marketplace records use Cloudflare D1 and uploaded files use Cloudflare R2 through Sites. ChatGPT/Sites handles authentication and hosting access. A configured AI brief provider receives the rough idea you explicitly submit to it; automatic AI submission does not occur.'], ['Purpose and retention', 'Data supports discovery, campaign collaboration, verification review and support enquiries. Records remain while your account exists. You can delete unpublished portfolio projects and remove your marketplace account from Settings after completing active engagements. Project records shared with collaborators are also removed by account deletion.'], ['Device preferences', 'The chosen visual theme is stored in your browser’s local storage. This preference contains no project or profile data. No advertising tracker is included in the application.'], ['Requests and questions', 'Use the signed-in Contact form to send a privacy enquiry. This policy describes the current application. The operator must review hosting-provider terms and any additional integrations before opening broader commercial access.']] },
    '/terms': { tag: 'CLEAR EXPECTATIONS, BETTER COLLABORATIONS', title: 'Terms of use.', desc: 'Last updated 12 October 2026.', sections: [['Marketplace participation', 'Provide accurate account, capability, portfolio and campaign information. Upload only content you are authorized to share and display. Do not impersonate others, misrepresent evidence or submit unlawful, abusive or infringing material.'], ['Scope and agreements', 'Brands, agencies and creators are responsible for agreeing price, deliverables, schedule, revisions, confidentiality, attribution and rights. An accepted invitation stores the agreed project scope. Discuss additional work and revised terms before exceeding that scope.'], ['Commercial and intellectual-property rights', 'AI-generated content is not automatically free of third-party restrictions. Participants must check tool/model terms, source assets, likeness permissions and intended commercial usage. A rights request in a campaign does not by itself transfer ownership or grant a license.'], ['Capabilities and verification', 'Unreviewed profile information is self-declared. Evidence submitted, under review, verified and rejected are distinct states. Verification refers only to the reviewed claim and does not certify copyright ownership or guarantee a project outcome.'], ['Payments and delivery', 'CreaXa does not currently collect payments, hold escrow or settle invoices. Participants arrange payment directly. Submitted, approved, delivered and completed are creative-workflow states and do not prove payment settlement.'], ['Account security and removal', 'Sign-in is managed by ChatGPT. Keep your identity account secure. Marketplace account deletion is available in Settings after active engagements are completed and removes associated marketplace records.'], ['Disputes and support', 'Use the Contact form for support, abuse or rights-related enquiries. Project participants remain responsible for their agreements and disputes. Before wider commercial release, the operator must finalize business identity, applicable governing terms and operational support arrangements.']] }
};
function Info({ path }: any) { if (path === '/faq')
    return <div className="page info-page"><span className="eyebrow">GOOD QUESTIONS. CLEAR ANSWERS.</span><h1>A little more <em>clarity.</em></h1><FaqList /></div>; if (path === '/contact')
    return <div className="page info-page"><span className="eyebrow">LET’S KEEP THE CONVERSATION OPEN</span><h1>How can we <em>help?</em></h1><p className="large-copy">Account questions, creative-workflow issues, or a concern about published content. Send a private enquiry.</p><ContactForm /></div>; const info = INFO[path]; if (!info)
    return <div className="page"><Empty title="This page couldn’t be found." description="Explore the creative directory or return to the homepage." action="Back to CreaXa" href="/"/></div>; return <div className="page info-page"><span className="eyebrow">{info.tag}</span><h1>{info.title}</h1><p className="large-copy">{info.desc}</p>{info.sections.map(([h, p]: any) => <section key={h}><h2>{h}</h2><p>{p}</p></section>)}{!['/privacy', '/terms'].includes(path) && <div className="info-cta"><Button href={path === '/for-creators' ? '/signup' : '/app/brand/campaigns/new'}>{path === '/for-creators' ? 'Publish your perspective' : 'Start a campaign'}<ArrowUpRight size={18}/></Button><Button secondary href="/discover">Discover creators<ArrowUpRight size={18}/></Button></div>}</div>; }

